// Split-precision CSR prefill attention over prefix and extend KV pools.
// SPDX-License-Identifier: MIT
// Copyright (C) 2024-2026, Advanced Micro Devices, Inc. All rights reserved.
#include <ATen/hip/HIPContext.h>
#include <ATen/ops/empty.h>
#include <ATen/ops/zeros.h>
#include <torch/library.h>
#include <cstdint>
#include "prefill.h"

void run(const at::Tensor& q_nope, const at::Tensor& q_rope,
         const at::Tensor& prefix_nope, const at::Tensor& prefix_rope,
         const at::Tensor& prefix_indices, const at::Tensor& prefix_indptr,
         const at::Tensor& extend_nope, const at::Tensor& extend_rope,
         const at::Tensor& extend_indices, const at::Tensor& extend_indptr,
         const at::Tensor& sinks, double softmax_scale, at::Tensor& output) {
    opus_mla_v4_prefill_fp8_kargs args{};
    args.q_nope_ptr = q_nope.data_ptr();
    args.q_rope_ptr = q_rope.data_ptr();
    args.unified_kv_nope_ptr = prefix_nope.data_ptr();
    args.unified_kv_rope_ptr = prefix_rope.data_ptr();
    args.kv_nope_ptr = extend_nope.data_ptr();
    args.kv_rope_ptr = extend_rope.data_ptr();
    args.attn_sink_ptr = sinks.data_ptr();
    args.out_ptr = output.data_ptr();
    args.kv_indices_prefix = prefix_indices.data_ptr<int>();
    args.kv_indptr_prefix = prefix_indptr.data_ptr<int>();
    args.kv_indices_extend = extend_indices.data_ptr<int>();
    args.kv_indptr_extend = extend_indptr.data_ptr<int>();
    args.N = q_nope.size(0);
    args.H = q_nope.size(1);
    args.total_pages = prefix_nope.size(0);
    args.total_tokens = extend_nope.size(0);
    args.stride_q_nope_n = q_nope.stride(0);
    args.stride_q_nope_h = q_nope.stride(1);
    args.stride_q_rope_n = q_rope.stride(0);
    args.stride_q_rope_h = q_rope.stride(1);
    args.stride_o_n = output.stride(0);
    args.stride_o_h = output.stride(1);
    args.stride_kv_nope_page = prefix_nope.stride(0);
    args.stride_kv_rope_page = prefix_rope.stride(0);
    args.softmax_scale = softmax_scale;
    const auto stream = at::hip::getCurrentHIPStream();

    int units = 0;
    TORCH_CHECK(hipDeviceGetAttribute(&units, hipDeviceAttributeMultiprocessorCount,
                                    q_nope.get_device()) == hipSuccess && units > 0,
                "cannot read the device compute-unit count");
    args.reverse_token_order = args.N >= 2 * units;
    using Traits = opus_mla_v4_prefill_a8w8_16mx8_32nx1_traits<16, 32, 8, fp8_t, bf16_t, bf16_t>;
    const int hblocks = (args.H + Traits::Q_TILE_SIZE * Traits::T_M - 1) / (Traits::Q_TILE_SIZE * Traits::T_M);
    if (args.N > units && 2 * (args.N - units) <= units) {
        using Split = opus_mla_v4_prefill_a8w8_16mx8_32nx1_split_traits<16, 32, 8, fp8_t, bf16_t, bf16_t>;
        const int tail = args.N - units;
        constexpr int splits = 2;
        constexpr int stride = Split::Q_TILE_SIZE * Split::D_HEAD_SIZE + 2 * 64;
        auto counters = at::zeros({int64_t(tail) * hblocks * Split::NUM_WARPS * 2}, q_nope.options().dtype(at::kInt));
        auto partials = at::empty({int64_t(tail) * splits * hblocks * Split::NUM_WARPS * stride}, q_nope.options().dtype(at::kFloat));
        opus_mla_v4_prefill_fp8_split_kargs split{};
        split.base = args;
        split.cnt = counters.data_ptr<int>();
        split.part = partials.data_ptr<float>();
        split.n_whole = units;
        split.split = splits;
        opus_mla_v4_prefill_a8w8_16mx8_32nx1_split_kernel<Split>
            <<<dim3(units + tail * splits, hblocks, 1), Split::BLOCK_SIZE, 0, stream>>>(split);
    } else {
        opus_mla_v4_prefill_a8w8_16mx8_32nx1_kernel<Traits>
            <<<dim3(args.N, hblocks, 1), Traits::BLOCK_SIZE, 0, stream>>>(args);
    }

}
#define TORCH_LIBRARY_EXPAND(ns, m) TORCH_LIBRARY(ns, m)
TORCH_LIBRARY_EXPAND(TORCH_EXTENSION_NAME, m) {
    m.def("run(Tensor q_nope, Tensor q_rope, Tensor prefix_nope, Tensor prefix_rope, "
          "Tensor prefix_indices, Tensor prefix_indptr, Tensor extend_nope, Tensor extend_rope, "
          "Tensor extend_indices, Tensor extend_indptr, Tensor sinks, float softmax_scale, "
          "Tensor(a!) output) -> ()", &run);
}

