    [[no_unique_address]] tdm_groups23<needs_groups23, group2_dword3_const, group3_dword2_const> groups23{};
    OPUS_H_D static u32_t g(i32_t x) { return u32_t(x); }
    OPUS_H_D void set_lds_addr          (u32_t v) { group0[1] = i32_t(v); }
    OPUS_H_D void set_global_addr       (u64_t v) { group0[2] = i32_t(u32_t(v)); group0[3] = i32_t((g(group0[3]) & 0xFE000000u) | u32_t((v >> 32) & 0x01FFFFFFu)); }
    OPUS_H_D void set_tensor_dim0       (u32_t  v) { group1[1] = i32_t((g(group1[1]) & 0x0000FFFFu) | (v << 16)); group1[2] = i32_t((g(group1[2]) & 0xFFFF0000u) | (v >> 16)); }
    OPUS_H_D void set_tensor_dim1       (u32_t  v) { group1[2] = i32_t((g(group1[2]) & 0x0000FFFFu) | (v << 16)); group1[3] = i32_t((g(group1[3]) & 0xFFFF0000u) | (v >> 16)); }
    OPUS_H_D void set_tensor_dim0_stride(u64_t  v) { group1[5] = i32_t(u32_t(v)); group1[6] = i32_t((g(group1[6]) & 0xFFFF0000u) | u32_t((v >> 32) & 0xFFFFu)); }
    OPUS_H_D void set_tensor_dim1_stride(u64_t  v) { group1[6] = i32_t((g(group1[6]) & 0x0000FFFFu) | (u32_t(v) << 16)); group1[7] = i32_t(u32_t(v >> 16)); }
    OPUS_H_D void set_tensor_dim2       (u32_t  v) { groups23.group2[0] = i32_t(v); }
    OPUS_H_D void set_tensor_dim3       (u32_t  v) { groups23.group2[1] = i32_t(v); }
    OPUS_H_D void set_tensor_dim2_stride(u64_t  v) { groups23.group2[2] = i32_t(u32_t(v)); groups23.group2[3] = i32_t((g(groups23.group2[3]) & 0xFFFF0000u) | u32_t((v >> 32) & 0xFFFFu)); }
    OPUS_H_D void set_tensor_dim3_stride(u64_t  v) { groups23.group3[0] = i32_t(u32_t(v)); groups23.group3[1] = i32_t((g(groups23.group3[1]) & 0xFFFF0000u) | u32_t((v >> 32) & 0xFFFFu)); }
    OPUS_H_D void set_tensor_dim4       (u32_t  v) { groups23.group3[1] = i32_t((g(groups23.group3[1]) & 0x0000FFFFu) | (v << 16)); groups23.group3[2] = i32_t((g(groups23.group3[2]) & 0xFFFF0000u) | (v >> 16)); }
    OPUS_H_D void set_workgroup_mask    (u32_t  v) { group1[0] = i32_t((g(group1[0]) & 0xFFFF0000u) | (v & 0xFFFFu)); }
    OPUS_H_D void set_tile_dim1         (u32_t  v) { group1[4] = i32_t((g(group1[4]) & 0xFFFF0000u) | (v & 0xFFFFu)); }
};
