template<typename T, class S>
__device__ inline auto load_mxscl_b128(S& s_k_nope, int slot_off) {
    using D_NOPE = typename T::D_NOPE;
    constexpr int row_stride  = T::smem_linear_wave_nope + T::smem_padding_32B_nope;
    constexpr int mxscl_chunk = T::D_NOPE_SIZE / T::D_128B_NOPE_SIZE;
    constexpr int mxscl_col   = T::D_NOPE_SIZE % T::D_128B_NOPE_SIZE;
    constexpr int e_stride    = (T::W_N / T::smem_n_rpt) * T::D_128B_NOPE_SIZE;
    static_assert(T::GEMM0_E_N == 2 && T::W_N == 16 && T::smem_n_rpt == 4, "mxscl_b128 layout assumptions");
    int lane;
    asm volatile("v_mbcnt_lo_u32_b32 %0, -1, 0\n\tv_mbcnt_hi_u32_b32 %0, -1, %0" : "=v"(lane));
    const int lane_n = lane & 15;
    const int row_off = (lane_n & 3) * row_stride + (lane_n >> 2) * T::D_128B_NOPE_SIZE
                      + mxscl_chunk * T::smem_n_rpt * row_stride + mxscl_col + slot_off;
    const opus::u32_t g4 = static_cast<opus::u32_t>(lane >> 4) * 0x0101u;
    const opus::u32_t sel_lo = 0x0c0c0400u + g4;
    const opus::u32_t hi_base = __builtin_amdgcn_alignbit(sel_lo, sel_lo, 16);
    const opus::u32_t sel_hi = (lane >= 32) ? ((hi_base & 0x00ffffffu) | 0x0c000000u) : hi_base;
    opus::vector_t<opus::u32_t, 2> res;
    opus::static_for<T::GEMM0_E_N>([&](auto e) {
        auto raw = s_k_nope.template load<16>(row_off + e.value * e_stride);
        auto d = __builtin_bit_cast(opus::vector_t<opus::u32_t, 4>, raw);
        const opus::u32_t lo = __builtin_amdgcn_perm(d[1], d[0], sel_lo);
        const opus::u32_t hi = __builtin_amdgcn_perm(d[3], d[2], sel_hi);
        res[e.value] = lo | hi;
    });
    return __builtin_bit_cast(opus::vector_t<D_NOPE, 8>, res);
}
