            const vector_t<float, 2> mlu = __builtin_bit_cast(vector_t<float, 2>,
                __builtin_amdgcn_raw_buffer_load_b64(rs, ml_off, so, AUX_SC1));
            const D_ACC f = __builtin_amdgcn_exp2f(mlu[0] - m_new);
            l_row += f * mlu[1];
            static_for<OV / 4 / MG>([&](auto g) {
                vector_t<float, 4> t4[MG];
                static_for<MG>([&](auto j) {
                    t4[j.value] = __builtin_bit_cast(vector_t<float, 4>, __builtin_amdgcn_raw_buffer_load_b128(rs,
                        ((g.value * MG + j.value) * T::WARP_SIZE + lane_id_s) * 16, so, AUX_SC1));
                });
                static_for<MG>([&](auto j) {
                    constexpr int b = (g.value * MG + j.value) * 4;
                    v_o[b + 0] += f * t4[j.value][0]; v_o[b + 1] += f * t4[j.value][1];
                    v_o[b + 2] += f * t4[j.value][2]; v_o[b + 3] += f * t4[j.value][3];
                });
            });
        }
        m_row = m_new;
    }
    D_ACC sink_log2 = smem_sink[warp_id * T::WARP_SIZE + lane_id_s] * LOG2_E;
    D_ACC m_final = max(m_row, sink_log2);
    D_ACC alpha = __builtin_amdgcn_exp2f(m_row - m_final);
    D_ACC l_final = l_row * alpha + __builtin_amdgcn_exp2f(sink_log2 - m_final);
    D_ACC o_scale = (l_final > D_ACC(0.0f)) ? (alpha / l_final) : D_ACC(0.0f);
    scale_output_tile<T>(v_o, o_scale);
