    int warp_id_o = __builtin_amdgcn_readfirstlane(thread_id_x() / T::WARP_SIZE);
    auto v_o_out = cast<D_OUT>(v_o);
    static_assert(T::GEMM1_E_M == 1 && T::VEC_O == 4 && T::W_M == 16 && T::W_N == 16, "O store layout");
    constexpr int NB = T::D_HEAD_SIZE / T::W_N;
    auto& o32 = reinterpret_cast<vector_t<u32_t, NB * 2>&>(v_o_out);
    const int row = lane_id_o & 3;
    const int hq = ((lane_id_o >> 4) << 2) | ((lane_id_o >> 2) & 3);
    const int bp_addr = ((row << 4) | hq) << 2;
    const int head = h_block_start + warp_id_o * T::Q_TILE_SIZE + hq;
    D_OUT* o_ptr = reinterpret_cast<D_OUT*>(kargs.out_ptr) + static_cast<int64_t>(q_token_idx) * kargs.stride_o_n
