            vector_t<u32_t, 2> s1 = __builtin_amdgcn_permlane16_swap(o32[4 * k + 1], o32[4 * k + 3], false, false);
            vector_t<u32_t, 4> w;
            w[0] = s0[0]; w[1] = s1[0]; w[2] = s0[1]; w[3] = s1[1];
            static_for<4>([&](auto i) {
                w[i.value] = static_cast<u32_t>(__builtin_amdgcn_ds_bpermute(bp_addr, static_cast<int>(w[i.value])));
            });
            *reinterpret_cast<vector_t<u32_t, 4>*>(o_ptr + k * 2 * T::W_N) = w;
        });
