template<typename T, typename V, typename S>
__device__ inline typename T::D_ACC attn_row_max(const V& v_s, S& s_m, int warp_id, int lane_id) {
    using D_ACC = typename T::D_ACC;
    constexpr opus::index_t s_len = opus::vector_traits<V>::size();
    D_ACC row_max = -1e30f;
    opus::static_for<s_len>([&](auto i) {
        row_max = max(row_max, v_s[i.value]);
    });
    opus::vector_t<opus::u32_t, 2> res32 = __builtin_amdgcn_permlane32_swap(aklr_bit_cast<opus::u32_t>(row_max), aklr_bit_cast<opus::u32_t>(row_max), false, true);
    row_max = max(aklr_bit_cast<float>(res32.x), aklr_bit_cast<float>(res32.y));
    opus::vector_t<opus::u32_t, 2> res16 = __builtin_amdgcn_permlane16_swap(aklr_bit_cast<opus::u32_t>(row_max), aklr_bit_cast<opus::u32_t>(row_max), false, true);
    row_max = max(aklr_bit_cast<float>(res16.x), aklr_bit_cast<float>(res16.y));
    int row_idx = lane_id % T::W_M;
    store(s_m, row_max, row_idx * T::T_N + (warp_id % T::T_N));
    s_waitcnt_lgkmcnt(0_I);
    __builtin_amdgcn_s_barrier();
    auto max_warps = opus::load<T::T_N>(s_m, row_idx * T::T_N);
    opus::static_for<T::T_N>([&](auto i) {
        row_max = max(row_max, max_warps[i.value]);
    });
    return row_max;
}
