    row_sum = aklr_bit_cast<float>(res32.x) + aklr_bit_cast<float>(res32.y);
    opus::vector_t<opus::u32_t, 2> res16 = __builtin_amdgcn_permlane16_swap(aklr_bit_cast<opus::u32_t>(row_sum), aklr_bit_cast<opus::u32_t>(row_sum), false, true);
    row_sum = aklr_bit_cast<float>(res16.x) + aklr_bit_cast<float>(res16.y);
